// Node shim of the two SDK clients the connector uses. Same method names/shapes as the real SDK,
// so the built task scripts run unchanged. Targets the mock server (DT_MOCK_URL).
const base = (process.env.DT_MOCK_URL ?? "http://127.0.0.1:8787").replace(/\/$/, "");

export const credentialVaultClient = {
  async listCredentials() {
    return { credentials: [{ id: "CREDENTIALS_VAULT-MOCKBYNAME", name: "Anthropic console usage API key", type: "TOKEN", scopes: ["APP_ENGINE"] }] };
  },
  async getCredentialsDetails({ id }) {
    if (!id) throw new Error("mock vault: id required");
    // Real vault returns {type:"TOKEN", token} or {type:"USERNAME_PASSWORD", username, password}
    return { id, name: "mock Anthropic key", type: "TOKEN", token: process.env.MOCK_ANTHROPIC_KEY ?? "sk-ant-mock-key" };
  },
};

export const businessEventsClient = {
  async ingest({ body, type }) {
    const res = await fetch(`${base}/api/v2/bizevents/ingest`, {
      method: "POST",
      headers: { "content-type": type ?? "application/json", authorization: "Api-Token mock-sdk" },
      body: typeof body === "string" ? body : JSON.stringify(body),
    });
    if (!res.ok) throw new Error(`mock ingest failed: HTTP ${res.status} ${await res.text()}`);
    return {};
  },
};
